fun selectAppearanceProfile(value: JSONObject, style: String, mode: String): JSONObject {
    val profiles = (value.optJSONObject("profiles") ?: JSONObject()).copy()
    val old = value.optJSONObject("colors")?.copy() ?: JSONObject()
    listOf("background", "sidebar", "text").forEach { key -> old.put(key, value.opt(key)) }
    profiles.put("${value.text("style", "modern")}-${value.text("mode", "dark")}", old)
    val defaults = profileDefaults.getJSONObject("$style-$mode")
    val colors = defaults.getJSONObject("colors").copy()
    profiles.optJSONObject("$style-$mode")?.let { saved -> saved.keys().forEach { key -> colors.put(key, saved.opt(key)) } }
    val result = value.copy().put("style", style).put("mode", mode).put("profiles", profiles).put("preset", "modern").put("accent", defaults.getString("accent"))
    listOf("background", "sidebar", "text").forEach { key -> result.put(key, colors.remove(key)) }
    return result.put("colors", colors)
}
